package org.sopt.solply_server.domain.place.cache.town;

/**
 * 캐시 한 항목의 이름. <b>번호가 키의 일부라는 것이 이 설계의 안전장치다.</b>
 *
 * <p>같은 동네의 다른 번호는 서로 다른 항목이라, 오래 걸린 옛 적재가 뒤늦게 끝나도 자기 키에만
 * 쓴다 — 이미 올라와 있는 새 번호 항목을 덮을 경로 자체가 없다. 번호를 항목 <em>안</em>에 두고
 * 키를 동네로만 잡았다면 그 덮어쓰기를 막는 비교 로직을 따로 지켜야 했을 것이다.
 *
 * <p><b>구버전 보관도 이 키가 만든다.</b> v1과 v2가 서로 다른 항목이므로 새 번호가 올라와도 옛
 * 번호가 밀려나지 않고, 진행 중인 스크롤이 자기 번호로 다음 페이지를 이어받는다.
 */
public record TownCacheKey(long townId, long version) {
}
